package net.civeira.phylax.features.document.snippetversion.domain.valueholder;

import java.util.Optional;

import lombok.RequiredArgsConstructor;
import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.features.document.snippetversion.domain.SnippetVersion;
import net.civeira.phylax.features.document.snippetversion.domain.valueobject.SubjectVO;

@RequiredArgsConstructor
public class SubjectValueHolder<T> {

  /**
   * @autogenerated ValueHolderGenerator
   */
  private final T holder;

  /**
   * @autogenerated ValueHolderGenerator
   */
  private Optional<SubjectVO> value = Optional.empty();

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<String> getSubject() {
    return value.flatMap(SubjectVO::getSubject);
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public Optional<SubjectVO> getSubjectValue() {
    return value;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param original
   * @param fails
   * @return
   */
  public SubjectVO readSubject(final Optional<SnippetVersion> original,
      final ConstraintFailList fails) {
    return value
        .orElse(original.map(SnippetVersion::getSubjectValue).orElseGet(SubjectVO::nullValue));
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param subject
   * @return
   */
  public T subject(SubjectVO subject) {
    this.value = Optional.of(subject);
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param subject
   * @return
   */
  public T subject(Optional<SubjectVO> subject) {
    this.value = subject;
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param subject
   * @return
   */
  public T subject(String subject) {
    this.value = Optional.of(SubjectVO.from(subject));
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T subjectNull() {
    this.value = Optional.empty();
    return this.holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @return
   */
  public T unsetSubject() {
    value = Optional.empty();
    return holder;
  }

  /**
   * @autogenerated ValueHolderGenerator
   * @param field
   * @return
   */
  public T unsetSubjectIfMatches(final String field) {
    if ("subject".equals(field)) {
      value = Optional.empty();
    }
    return holder;
  }
}
